// Selected official ActivityInfoUI; generated by prepare_activity_battle_page_support.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
namespace Zjcs.Official.ActivityBattleUI
{
using Object = UnityEngine.Object;
using UnityEngine;

public class ActivityInfoUI : WorldInitializedUI
{
	[SerializeField]
	protected WorldShowRemainTimeInfo mShowRemainTimeInfo;

	[SerializeField]
	private WorldMultiLanguageText mNameTxt;

	private ActivityDisplayData mData;

	private bool mPreviewMode;

	public void Init(ActivityDisplayData data)
	{
		InitWrapper(() =>
		{
			mPreviewMode = false;
			mData = data;
		});
	}

	public void InitPreview(ActivityDisplayData data)
	{
		InitWrapper(() =>
		{
			mPreviewMode = true;
			mData = data;
		});
	}

	protected override void OnEnableAndInited()
	{
		base.OnEnableAndInited();
		if (!mPreviewMode) RefreshTime(mData);
		if (mNameTxt != null) mNameTxt.SetKey("{0}",
			(mNameTxt.Localizer ?? WorldMultiLanguageText.Localize)(mData.NameKey));
	}

	protected virtual void RefreshTime(ActivityDisplayData data)
	{
		if ((Object)(object)mShowRemainTimeInfo != (Object)null)
		{
			mShowRemainTimeInfo.Init(data.EndDate, 1f, null, WorldTimeSpanFormatType.Brief);
		}
	}
}

}
